mapper.select:
SELECT COUNT(*)
FROM OP_DATA_BOARD N


		AND SUB_CATEGORY = #{subCategory}


		AND CATEGORY_TEAM LIKE CONCAT('%', #{categoryTeam}, '%')



			AND SUBJECT LIKE CONCAT('%', #{query}, '%')


			AND CONTENT LIKE CONCAT('%', #{query}, '%')



		AND NOTICE_FLAG = #{noticeFlag}


		AND (VISIBLE_TYPE = #{visibleType} OR VISIBLE_TYPE = 1)


		AND DATE_FORMAT(N.CREATED_DATE,'%Y%m%d') BETWEEN #{startCreateDate} AND #{endCreateDate}

SELECT A.DATA_ID ,A.SUBJECT ,A.URL ,A.CATEGORY_TEAM ,crypto_dec('normal', A.USER_NAME, '', 0) AS USER_NAME ,A.PASSWORD ,A.EMAIL ,A.CONTENT ,A.HITS ,A.BOARD_CODE ,A.SUB_CATEGORY ,A.CREATED_DATE ,A.TARGET_OPTION ,A.REL_OPTION ,A.NOTICE_FLAG ,A.VISIBLE_TYPE ,A.SELLER_SELECT_FLAG ,A.NEW_FLAG ,A.USE_YN FROM ( SELECT N.DATA_ID, N.SUBJECT, N.URL, N.CATEGORY_TEAM, N.USER_NAME, N.PASSWORD, N.EMAIL, N.CONTENT, N.HITS, N.BOARD_CODE, N.SUB_CATEGORY, N.CREATED_DATE, N.TARGET_OPTION, N.REL_OPTION, N.NOTICE_FLAG, N.VISIBLE_TYPE, N.SELLER_SELECT_FLAG, CASE WHEN DATE_FORMAT(ADDDATE(STR_TO_DATE(N.CREATED_DATE,'%Y%m%d%H%i%s'), INTERVAL 3 DAY),'%Y%m%d%H%i%s') >= THEN 'Y' ELSE 'N' END AS NEW_FLAG, N.USE_YN FROM OP_DATA_BOARD N
AND (VISIBLE_TYPE = #{visibleType} OR VISIBLE_TYPE = 1)
AND SUB_CATEGORY = #{subCategory}
AND CATEGORY_TEAM LIKE CONCAT('%', #{categoryTeam}, '%')
AND NOTICE_FLAG = #{noticeFlag}
AND SUBJECT LIKE CONCAT('%', #{query}, '%')
AND CONTENT LIKE CONCAT('%', #{query}, '%')
AND DATE_FORMAT(N.CREATED_DATE,'%Y%m%d') BETWEEN #{startCreateDate} AND #{endCreateDate}
GROUP BY N.DATA_ID ORDER BY N.NOTICE_FLAG DESC, N.DATA_ID DESC ) A

mapper.update:
UPDATE OP_DATA_BOARD
SET HITS = HITS + 1
WHERE DATA_ID = #{value}

mapper.select:
SELECT DATA_ID, SUBJECT, CASE WHEN URL IS NULL OR URL = '' THEN CONCAT('/board/view/',DATA_ID) ELSE TRIM(URL) END AS URL , CASE WHEN URL IS NULL OR URL = '' THEN 0 ELSE 1 END AS URL_TYPE , CATEGORY_TEAM, TARGET_OPTION, REL_OPTION, SUB_CATEGORY, CREATED_DATE FROM (
SELECT * FROM ( SELECT DATA_ID, SUBJECT, URL, #{teamCode} AS CATEGORY_TEAM, TARGET_OPTION, REL_OPTION, SUB_CATEGORY, CREATED_DATE FROM OP_DATA_BOARD WHERE CATEGORY_TEAM LIKE CONCAT('%', #{teamCode}, '%') ORDER BY DATA_ID DESC LIMIT 5 ) T#{index}
) T

mapper.insert:
INSERT INTO OP_DATA_BOARD_FILE (
	DATA_FILE_ID
	, DATA_ID
	, FILE_NAME
	, FILE_TY
	, ORDERING
	, CREATED_DATE
	, ORG_FILE_NAME
) VALUES (
	#{dataFileId}
	, #{dataId}
	, #{fileName}
	, #{fileTy}
	, (SELECT IFNULL(MAX(ORDERING)+1, 1) FROM OP_DATA_BOARD_FILE WHERE DATA_ID = #{dataId})
	, 
	, #{orgFileName}
)
